    E -- "fora da gramática" --> X1
    E -- v1 --> F{"tamanho até 87428?"}
    F -- não --> X3["secret_size"]
    F -- sim --> G{"base64 padrão, 28 bytes ou mais?"}
    G -- não --> X1
    G -- sim --> H{"AES-256-GCM abre com a AAD do escopo?"}
    H -- não --> X4["secret_decrypt"]
